// ------------------------------------------------------------ scenario 5: client resource leak (own stack)
function lsofCount(pid) {
  try {
    const o = execFileSync("lsof", ["-nP", "-a", "-p", String(pid), "-i", "TCP"], { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] });
    const lines = o.split("\n").slice(1).filter(Boolean);
    const states = {};
    for (const l of lines) { const m = /\((\w+)\)\s*$/.exec(l); const s = m ? m[1] : "?"; states[s] = (states[s] ?? 0) + 1; }
    return { total: lines.length, states };
  } catch { return { total: 0, states: {} }; }
}
function fdCount(pid) { try { return execFileSync("lsof", ["-nP", "-p", String(pid)], { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).split("\n").length - 2; } catch { return -1; } }
async function s5(durationS = 300) {
  const out = { samples: [], phases: [] };
  const eng = mkEngine(); eng.start();
  await waitFor(() => eng.healthy(), 20);
  const ops = new Ops(eng, { push: A.q2, pushEvery: 300, stateEvery: 200, skipEvery: 500, healthEvery: 100 }).begin();
  const sample = (tag) => {
    globalThis.gc?.();
    const m = process.memoryUsage(); const ar = process.getActiveResourcesInfo(); const cnt = {};
    for (const r of ar) cnt[r] = (cnt[r] ?? 0) + 1;
    const l = lsofCount(process.pid);
    out.samples.push({ tS: +now().toFixed(0), tag, rssMB: +(m.rss / 1048576).toFixed(1), heapUsedMB: +(m.heapUsed / 1048576).toFixed(2), externalMB: +(m.external / 1048576).toFixed(2), tcpSockets: l.total, tcpStates: l.states, fds: fdCount(process.pid), activeResources: cnt, inflightCalls: ops.inflight, recs: ops.recs.length });
    if (ops.recs.length > 2000) ops.recs.splice(0, ops.recs.length - 200); // the recorder itself must not grow
  };
  // engine present / absent / paused, in 20 s phases
  const plan = ["present", "absent", "present", "paused", "present", "absent", "present", "absent", "present", "paused", "present", "absent", "present", "paused", "present"];
  const end = now() + durationS;
  let i = 0;
  sample("start");
  const sampler = setInterval(() => sample(plan[i % plan.length]), 10000);
  while (now() < end) {
    const ph = plan[i % plan.length];
    out.phases.push({ phase: ph, tS: +now().toFixed(0) });
    if (ph === "absent") await docker(["stop", "-t", "1", cname("liquidsoap")]);
    if (ph === "paused") await docker(["pause", cname("liquidsoap")]);
    await sleep(Math.min(20000, Math.max(0, (end - now()) * 1000)));
    if (ph === "absent") await docker(["start", cname("liquidsoap")]);
    if (ph === "paused") await docker(["unpause", cname("liquidsoap")]);
    i++;
  }
  clearInterval(sampler); ops.end();
  await docker(["unpause", cname("liquidsoap")]); await docker(["start", cname("liquidsoap")]);
  await sleep(10000);
  sample("settled-after-stop-ops");
  out.healthyRejects = ops.healthyRejects; out.maxInflightCalls = ops.maxInflight;
  out.finalHealthy = await eng.healthy();
  await eng.close();
  await sleep(500);
  sample("after-close");
  return out;
}

// ------------------------------------------------------------ scenario 6: disk (tmpfs) full on Icecast logs
async function s6() {
  const out = { note: "The generated Liquidsoap script writes nothing to disk (no output.file, no log file); the only writer in the test stack is Icecast (access/error logs under /var/log/icecast). A 256 KB tmpfs is mounted there and filled by listener connections." };
  writeFileSync(join(runDir, "tmpfs.yml"), `services:\n  icecast:\n    tmpfs:\n      - /var/log/icecast:size=256k,mode=1777,uid=1000\n`);
  extraCompose = ["-f", join(runDir, "tmpfs.yml")];
  const up = await compose(["up", "-d", "--force-recreate", "icecast"], 120000);
  out.recreateRc = up.code;
  if (up.code !== 0) { out.note += " NOT RUN: " + up.out.slice(-200); return out; }
  const m = await waitFor(mount, 60, 500);
  out.mountBackS = m === undefined ? null : +m.toFixed(1);
  const df = () => docker(["exec", cname("icecast"), "df", "-k", "/var/log/icecast"]).then((r) => r.out.trim().split("\n").at(-1));
  out.dfBefore = await df();
  const eng = mkEngine(); eng.start();
  const L = new Listener().start();
  await sleep(5000);
  // fill: many short listener connections (each writes an access.log line); bounded to 90 s
  const t = performance.now(); let n = 0;
  while ((performance.now() - t) < 90000) {
    await Promise.all(Array.from({ length: 40 }, () => new Promise((r) => { const q = http.get({ host: "127.0.0.1", port: CFG.ice, path: "/radio-nope-" + (n++), agent: false, timeout: 2000 }, (res) => { res.resume(); res.on("end", r); res.on("close", r); }); q.on("error", r); q.on("timeout", () => { q.destroy(); r(); }); })));
    { const d = await df(); if (/\s100%\s/.test(d)) { out.dfFull = d; break; } }
  }
  out.requestsSent = n; out.dfAfterFill = await df();
  await sleep(1000);
  const mk = L.mark();
  await sleep(20000);
  out.listenerWhileFull = { addedAudioSeconds: +(L.mark() - mk).toFixed(1), windowS: 20 };
  out.mountStillPresent = await mount();
  out.healthy = await eng.healthy();
  out.icecastRunning = (await docker(["inspect", "-f", "{{.State.Running}} restarts={{.RestartCount}}", cname("icecast")])).out.trim();
  out.icecastLogTail = (await docker(["logs", "--tail", "5", cname("icecast")])).out.split("\n").slice(-6);
  out.listener = L.stats();
  L.stop(); await eng.close();
  return out;
}

